def binary_search(nums, target):
    n = len(nums)
    low, high = (0, n - 1)
    while low <= high:
        mid = low + (high - low) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            high = mid - 1
        else:
            low = mid + 1
    return -1
